          "h": 300
        }
      },
      {
        "item": "viz_16",
        "type": "block",
        "position": {
          "x": 720,
          "y": 1030,
          "w": 720,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "input_global_trp",
      "input_host"
    ]
  }
}
